CREATE POLICY customer_select ON etidealcrm.customer FOR SELECT TO authenticated USING (dealership_id = (SELECT etidealcrm.current_dealership_id()) AND (SELECT etidealcrm.can_read_leads() OR etidealcrm.can_read_deals()));
CREATE POLICY customer_write ON etidealcrm.customer FOR ALL TO authenticated USING (dealership_id = (SELECT etidealcrm.current_dealership_id()) AND (SELECT etidealcrm.can_write_all_leads() OR etidealcrm.has_role('salesperson','accounting'))) WITH CHECK (dealership_id = (SELECT etidealcrm.current_dealership_id()));
CREATE POLICY lead_select ON etidealcrm.lead FOR SELECT TO authenticated USING (dealership_id = (SELECT etidealcrm.current_dealership_id()) AND (SELECT etidealcrm.can_read_leads()) AND ((SELECT NOT etidealcrm.has_role('salesperson')) OR assigned_to = (SELECT auth.uid()) OR assigned_to IS NULL));
CREATE POLICY lead_insert ON etidealcrm.lead FOR INSERT TO authenticated WITH CHECK (dealership_id = (SELECT etidealcrm.current_dealership_id()) AND ((SELECT etidealcrm.can_write_all_leads()) OR (SELECT etidealcrm.has_role('salesperson'))));
CREATE POLICY lead_update ON etidealcrm.lead FOR UPDATE TO authenticated USING (dealership_id = (SELECT etidealcrm.current_dealership_id()) AND ((SELECT etidealcrm.can_write_all_leads()) OR (assigned_to = (SELECT auth.uid()) AND (SELECT etidealcrm.has_role('salesperson'))))) WITH CHECK (dealership_id = (SELECT etidealcrm.current_dealership_id()));
CREATE POLICY lead_event_select ON etidealcrm.lead_event FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM etidealcrm.lead l WHERE l.id = lead_id AND l.dealership_id = (SELECT etidealcrm.current_dealership_id())) AND (SELECT etidealcrm.can_read_leads()));
